import{_ as i,o as a,c as t,a3 as r,j as e,a as o}from"./chunks/framework.z_KJ15Ep.js";const c=JSON.parse('{"title":"Programmierung, Datenquellen und Subreports","description":"","frontmatter":{"title":"Programmierung, Datenquellen und Subreports","source_pageid":1613,"source_revision":6784},"headers":[],"relativePath":"reporting/programmierung/programmierung-sonderlogik-themenuebersicht.md","filePath":"reporting/programmierung/programmierung-sonderlogik-themenuebersicht.md"}'),s={name:"reporting/programmierung/programmierung-sonderlogik-themenuebersicht.md"};function u(l,n,m,d,g,h){return a(),t("div",null,[...n[0]||(n[0]=[r('<h1 id="programmierung-datenquellen-und-subreports" tabindex="-1">Programmierung, Datenquellen und Subreports <a class="header-anchor" href="#programmierung-datenquellen-und-subreports" aria-label="Permalink to &quot;Programmierung, Datenquellen und Subreports&quot;">​</a></h1><p>Wählen Sie die passende Erweiterung: Ereigniscode mit Object Pascal, eigene Datenquellen oder dynamisch nachgeladene Subreports. Zum Nachschlagen steht die RAP-Funktionsreferenz bereit.</p><p><a href="/reporting/reportdesigner/reportdesigner-schnelleinstieg.html">Den passenden Einstieg in den Reportdesigner finden</a></p><h2 id="programmierung-innerhalb-von-reports" tabindex="-1">Programmierung innerhalb von Reports <a class="header-anchor" href="#programmierung-innerhalb-von-reports" aria-label="Permalink to &quot;Programmierung innerhalb von Reports&quot;">​</a></h2>',4),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),o("Achtung")]),e("p",null,"Diese Artikel richten sich an technisch versierte Anwender, die über Basis-Reports hinaus dynamische oder programmierte Ausgaben erzeugen wollen.")],-1),r('<p>Diese Seite listet Artikel rund um die erweiterte Nutzung des Reporteditors in <strong>SchILD-NRW 3</strong>, insbesondere programmatische Möglichkeiten und spezielle Bausteine. Sie richtet sich an Anwender, die über die Basisfunktionen hinaus dynamische Logik, eigene Datenquellen oder wiederverwendbare Subreports einsetzen möchten.</p><p>Der Reportdesigner in SchILD-NRW 3 unterstützt die Programmiersprache Object Pascal. Dadurch können Reports um dynamisches Verhalten erweitert werden – von einfachen Sichtbarkeitsabfragen bis hin zu komplexen Berechnungen, Datenmanipulationen oder Benutzerinteraktionen.</p><h3 id="programmierung-eigene-datenquellen-funktionen" tabindex="-1">Programmierung, eigene Datenquellen, Funktionen <a class="header-anchor" href="#programmierung-eigene-datenquellen-funktionen" aria-label="Permalink to &quot;Programmierung, eigene Datenquellen, Funktionen&quot;">​</a></h3><ul><li><a href="/reporting/programmierung/programmierung-in-reports.html">Reports mit Object Pascal erweitern</a></li></ul><p>Erweitern Sie Reports durch eigene Programmierung, wenn die normalen Gestaltungsmöglichkeiten für Ihre Aufgabe nicht ausreichen.</p><ul><li><a href="/reporting/programmierung/eigene-datenquellen.html">Eigene Datenquellen für Reports definieren</a></li></ul><p>Definieren Sie eigene Datenquellen und Datenfelder, um eigene Ideen umzusetzen</p><ul><li><a href="/reporting/rap.html" title="RAP-Funktionen">RAP-Funktionen im Reportdesigner</a></li></ul><p>Nutzen Sie vorprogrammierte Funktionen</p><h3 id="subreports-dynamisch-nachladen" tabindex="-1">Subreports dynamisch nachladen <a class="header-anchor" href="#subreports-dynamisch-nachladen" aria-label="Permalink to &quot;Subreports dynamisch nachladen&quot;">​</a></h3><ul><li><a href="/reporting/programmierung/einen-subreport-dynamisch-in-einen-report-einbinden.html">Einen Subreport dynamisch einbinden</a></li></ul><p>Gemeinsame Bestandteile zur Laufzeit nachladen</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Programmierung_%26_Sonderlogik_Themen%C3%BCbersicht" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6784.</p>',14)])])}const b=i(s,[["render",u]]);export{c as __pageData,b as default};
